import Base

type W_Palette is Data:
  W_Palette{air: U32, stone: U32, dirt: U32, planks: U32}

type RF_Palette is Data:
  RF_Palette{air:U32,stone:U32,dirt:U32,planks:U32}

def V_palette_valid(palette:W_Palette) -> Bool:
  W_Palette{+air,+stone,+dirt,+planks} = palette
  U32.is_ne(air,stone) && U32.is_ne(air,dirt) && U32.is_ne(air,planks) &&
    U32.is_ne(stone,dirt) && U32.is_ne(stone,planks) && U32.is_ne(dirt,planks)

def RF_palette_valid(value:RF_Palette) -> Bool:
  RF_Palette{+air,+stone,+dirt,+planks} = value
  U32.is_ne(air,stone) && U32.is_ne(air,dirt) && U32.is_ne(air,planks) &&
    U32.is_ne(stone,dirt) && U32.is_ne(stone,planks) && U32.is_ne(dirt,planks)

def resource_palette(value:W_Palette) -> RF_Palette:
  W_Palette{air,stone,dirt,planks} = value
  RF_Palette{air,stone,dirt,planks}

law resource_palette_fields:
  for +air:U32
  for +stone:U32
  for +dirt:U32
  for +planks:U32
  {resource_palette(W_Palette{air,stone,dirt,planks}) == RF_Palette{air,stone,dirt,planks} : RF_Palette}

def resource_palette_fields(air,stone,dirt,planks):
  {==}

def palette_match(world:W_Palette,resources:RF_Palette) -> Bool:
  match world resources:
    case W_Palette{+air,+stone,+dirt,+planks} RF_Palette{+ra,+rs,+rd,+rp}:
      V_palette_valid(W_Palette{air,stone,dirt,planks}) &&
        RF_palette_valid(RF_Palette{ra,rs,rd,rp}) &&
        U32.is_eq(air,ra) && U32.is_eq(stone,rs) && U32.is_eq(dirt,rd) && U32.is_eq(planks,rp)

def palette_guard(valid:Bool) -> Result<&2,&2,String,Unit>:
  match valid:
    case False{}: Fail{"Palette:Mismatch"}
    case True{}: Done{Unit{}}

law mismatched_palette_rejects:
  {palette_guard(False{}) == Fail{"Palette:Mismatch"} : Result<&2,&2,String,Unit>}

def mismatched_palette_rejects():
  {==}

